import { FormEvent, useState } from "react";
import {
  Box,
  Button,
  MenuItem,
  Stack,
  TextField,
  Typography,
} from "@mui/material";
import toast from "react-hot-toast";
import masterData from "../../data/masterData.json";
import { getIcon } from "../../utils/iconMap";

interface LeadFormCardProps {
  defaultSpecialty?: string;
  compact?: boolean;
}

export default function LeadFormCard({
  defaultSpecialty = "",
  compact = false,
}: LeadFormCardProps) {
  const { leadForm, specialties } = masterData;
  const [form, setForm] = useState({
    fullName: "",
    phone: "",
    email: "",
    specialty: defaultSpecialty,
    city: "",
  });

  const handleSubmit = (event: FormEvent) => {
    event.preventDefault();
    if (!form.fullName.trim() || !form.phone.trim() || !form.email.trim()) {
      toast.error("Please fill in name, phone, and email.");
      return;
    }
    toast.success("Thanks! Our team will share program details shortly.");
    setForm({
      fullName: "",
      phone: "",
      email: "",
      specialty: defaultSpecialty,
      city: "",
    });
  };

  return (
    <Box
      component="form"
      onSubmit={handleSubmit}
      sx={{
        bgcolor: "#fff",
        borderRadius: 3,
        p: compact ? 2.5 : 3,
        boxShadow: "0 8px 32px rgba(0, 40, 100, 0.12)",
        border: "1px solid #E8EEF5",
      }}
    >
      <Typography
        variant="h6"
        sx={{ fontWeight: 700, color: "#0A2540", mb: 2.5, lineHeight: 1.3 }}
      >
        {leadForm.title}
      </Typography>

      <Stack spacing={1.75}>
        <TextField
          fullWidth
          placeholder={leadForm.fields.fullName}
          value={form.fullName}
          onChange={(e) => setForm((s) => ({ ...s, fullName: e.target.value }))}
          InputProps={{ sx: { bgcolor: "#F7F9FC" } }}
        />
        <TextField
          fullWidth
          placeholder={leadForm.fields.phone}
          value={form.phone}
          onChange={(e) => setForm((s) => ({ ...s, phone: e.target.value }))}
          InputProps={{
            sx: { bgcolor: "#F7F9FC" },
            startAdornment: (
              <Typography sx={{ mr: 1, color: "text.secondary", fontSize: 14 }}>
                +91
              </Typography>
            ),
          }}
        />
        <TextField
          fullWidth
          type="email"
          placeholder={leadForm.fields.email}
          value={form.email}
          onChange={(e) => setForm((s) => ({ ...s, email: e.target.value }))}
          InputProps={{ sx: { bgcolor: "#F7F9FC" } }}
        />
        <TextField
          select
          fullWidth
          value={form.specialty}
          onChange={(e) => setForm((s) => ({ ...s, specialty: e.target.value }))}
          SelectProps={{ displayEmpty: true }}
          InputProps={{ sx: { bgcolor: "#F7F9FC" } }}
        >
          <MenuItem value="" disabled>
            {leadForm.fields.specialty}
          </MenuItem>
          {specialties.map((item) => (
            <MenuItem key={item.id} value={item.id}>
              {item.name}
            </MenuItem>
          ))}
        </TextField>
        <TextField
          select
          fullWidth
          value={form.city}
          onChange={(e) => setForm((s) => ({ ...s, city: e.target.value }))}
          SelectProps={{ displayEmpty: true }}
          InputProps={{ sx: { bgcolor: "#F7F9FC" } }}
        >
          <MenuItem value="" disabled>
            {leadForm.fields.city}
          </MenuItem>
          {leadForm.cities.map((city) => (
            <MenuItem key={city} value={city}>
              {city}
            </MenuItem>
          ))}
        </TextField>

        <Button
          type="submit"
          variant="contained"
          fullWidth
          size="large"
          endIcon={(() => {
            const Icon = getIcon("arrow_forward");
            return <Icon />;
          })()}
          sx={{ mt: 0.5, py: 1.4, fontSize: 15 }}
        >
          {leadForm.submitLabel}
        </Button>
      </Stack>

      <Stack
        direction="row"
        justifyContent="space-between"
        spacing={1}
        sx={{ mt: 2.5, pt: 2, borderTop: "1px solid #E8EEF5" }}
      >
        {leadForm.trustPoints.map((point) => {
          const Icon = getIcon(point.icon);
          return (
            <Stack key={point.id} alignItems="center" spacing={0.5} sx={{ flex: 1 }}>
              <Icon sx={{ color: "primary.main", fontSize: 22 }} />
              <Typography
                variant="caption"
                sx={{ color: "text.secondary", textAlign: "center", lineHeight: 1.2 }}
              >
                {point.label}
              </Typography>
            </Stack>
          );
        })}
      </Stack>
    </Box>
  );
}
